struct VSOut { float4 pos : SV_POSITION; float2 uv : TEXCOORD0; };

float4 PSGBuffer(VSOut i) : SV_Target
{
    float2 uv = i.uv;
    float t = time_sim_ms * 0.001;
    float3 normal = normalize(float3(sin(uv.x * 6.28 + t), cos(uv.y * 6.28 + t * 0.5), 1.0));
    normal = normal * 0.5 + 0.5;
    return float4(normal, 1.0);
}

