[[vk::combinedImageSampler]] [[vk::binding(0, 2)]]
Texture2D gbufferTex : register(t0, space2);
[[vk::combinedImageSampler]] [[vk::binding(0, 2)]]
SamplerState gbufferSamp : register(s0, space2);

struct VSOut { float4 pos : SV_POSITION; float2 uv : TEXCOORD0; };

float4 PSLighting(VSOut i) : SV_Target
{
    float3 normal = gbufferTex.Sample(gbufferSamp, i.uv).rgb * 2.0 - 1.0;
    normal = normalize(normal);

    float2 lightPos = float2(mouse_x / resolution_x, mouse_y / resolution_y);
    float3 lightDir = normalize(float3(lightPos - i.uv, 0.5));

    float diff = saturate(dot(normal, lightDir));
    float3 albedo = float3(0.8, 0.6, 0.4);
    float3 color = albedo * (diff * 0.8 + 0.2);
    return float4(color, 1.0);
}
